#include <queue>
#include <iostream>

int main() {
    std::queue<int> q;
    q.push(10);
    q.push(20);

    while (!q.empty()) {
        // Step 1: Access the element (read)
        int value = q.front(); 
        std::cout << value << std::endl;

        // Step 2: Remove the element (destroy)
        q.pop(); 
    }
    // Note: pop() returns void, relying on front() for access.
}
